var knowledgeRouter = router({
  // Base de conhecimento COMPARTILHADA: todos os usuários (e a IA de todos) leem
  // os mesmos documentos. O admin cadastra scripts/políticas/regras e os
  // atendentes — junto com o assistente de IA — passam a enxergar tudo.
  list: protectedProcedure.query(async () => {
    return db.select().from(knowledgeDocuments).orderBy(knowledgeDocuments.createdAt);
  }),
  create: protectedProcedure.input(external_exports.object({
    title: external_exports.string().min(1).max(500),
    content: external_exports.string().min(1).max(1e5),
    category: external_exports.string().max(100).optional()
  })).mutation(async ({ input, ctx }) => {
    const [created] = await db.insert(knowledgeDocuments).values({
      userId: ctx.user.id,
      title: input.title,
      content: input.content,
      category: input.category
    }).returning();
    return created;
  }),
  delete: protectedProcedure.input(external_exports.object({ id: external_exports.number() })).mutation(async ({ input, ctx }) => {
    const where = ctx.user.role === "admin" ? eq(knowledgeDocuments.id, input.id) : and(eq(knowledgeDocuments.id, input.id), eq(knowledgeDocuments.userId, ctx.user.id));
    await db.delete(knowledgeDocuments).where(where);
    return { ok: true };
  })
});

// server/routers/workSessions.ts
init_zod();
init_trpc();
init_db2();
init_schema2();
init_drizzle_orm();
var workSessionsRouter = router({
  // Sessão atual do usuário: a aberta (ativa de preferência, senão pausada) ou, se
  // não há aberta, a última de hoje (encerrada) — assim as horas da manhã não somem
  // depois de encerrar e reiniciar. Campos acrescentados (contrato antigo intacto):
  //  - todayWorkedMs: horas de hoje (SP), somando todas as sessões, inclusive encerradas
  //  - todayOtherMs: o mesmo, sem a sessão devolvida (o cliente soma o relógio ao vivo dela)
  current: protectedProcedure.query(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const todayStart = spMidnight(now);
    const rows = await db.select().from(workSessions).where(and(
      eq(workSessions.userId, ctx.user.id),
      or2(
        eq(workSessions.status, "active"),
        eq(workSessions.status, "paused"),
        gte(workSessions.startedAt, todayStart),
        gte(workSessions.endedAt, todayStart)
      )
    )).orderBy(desc(workSessions.startedAt));
    const live = rows.filter((r5) => !isForgottenSession(r5, now));
    const session = live.find((r5) => r5.status === "active") ?? live.find((r5) => r5.status === "paused") ?? live.find((r5) => new Date(r5.startedAt) >= todayStart || r5.endedAt && new Date(r5.endedAt) >= todayStart);
    if (!session) return null;
    return {
      ...session,
      todayWorkedMs: todayWorkedMs(rows, now),
      todayOtherMs: todayWorkedMs(rows.filter((r5) => r5.id !== session.id), now)
    };
  }),
  // Start work — idempotente: no máximo uma sessão aberta por usuário.
  // Sessão aberta de DIA ANTERIOR é encerrada (fim limitado ao último sinal de vida,
  // não ao "agora"); sessão aberta de hoje é devolvida (retomada, se pausada). Só se
  // não houver nenhuma o INSERT condicional cria a nova — dois cliques simultâneos
  // não geram duas 'active'.
  start: protectedProcedure.input(external_exports.object({ dailyGoalHours: external_exports.number().min(1).max(24).default(8) })).mutation(async ({ input, ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const todayStart = spMidnight(now);
    const uid = ctx.user.id;
    const openWhere = (id2) => and(
      eq(workSessions.userId, uid),
      id2 === void 0 ? void 0 : eq(workSessions.id, id2),
      or2(eq(workSessions.status, "active"), eq(workSessions.status, "paused"))
    );
    const open = await db.select().from(workSessions).where(openWhere()).orderBy(desc(workSessions.startedAt));
    const todays = open.filter((s4) => new Date(s4.startedAt) >= todayStart);
    const keep = todays.find((s4) => s4.status === "active") ?? todays[0];
    for (const s4 of open) {
      if (keep && s4.id === keep.id) continue;
      await db.update(workSessions).set({ status: "ended", ...closeSessionValues(s4, now), pausedAt: null, updatedAt: now }).where(openWhere(s4.id));
    }
    if (keep) {
      if (keep.status === "paused") {
        const pausedMs = keep.pausedAt ? Math.max(0, now.getTime() - new Date(keep.pausedAt).getTime()) : 0;
        const [resumed] = await db.update(workSessions).set({ status: "active", pausedAt: null, totalPausedMs: (keep.totalPausedMs ?? 0) + pausedMs, updatedAt: now }).where(and(eq(workSessions.id, keep.id), eq(workSessions.status, "paused"))).returning();
        if (resumed) return resumed;
      } else {
        return keep;
      }
    }
    const ins = await db.execute(sql`
        INSERT INTO work_sessions (user_id, daily_goal_hours, status)
        SELECT ${uid}::integer, ${input.dailyGoalHours}::integer, 'active'
        WHERE NOT EXISTS (
          SELECT 1 FROM work_sessions WHERE user_id = ${uid}::integer AND status IN ('active', 'paused')
        )
        RETURNING id`);
    const newId = ins.rows[0]?.id;
    const [session] = await db.select().from(workSessions).where(newId !== void 0 ? eq(workSessions.id, newId) : openWhere()).orderBy(desc(workSessions.startedAt)).limit(1);
    return session;
  }),
  // Batimento: o cliente chama a cada 5 min com a aba visível e a sessão ativa. Só
  // atualiza updatedAt (último sinal de vida) — é o que impede uma sessão esquecida
  // aberta de virar 0 h ao ser encerrada (ver effectiveEndMs em lib/workHours.ts).
  // Sessão esquecida (de dia anterior, sem sinal há mais de 15 min) NÃO é atualizada:
  // o notebook que acorda no dia seguinte dispara o setInterval atrasado e, sem esta
  // condição, "ressuscitaria" a sessão e contaria a noite como trabalho. `updated: 0`
  // avisa o cliente para recarregar a sessão atual.
  heartbeat: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const { midnight, staleBefore } = heartbeatCutoffs(now);
    const rows = await db.update(workSessions).set({ updatedAt: now }).where(and(
      eq(workSessions.userId, ctx.user.id),
      eq(workSessions.status, "active"),
      or2(gte(workSessions.startedAt, midnight), gt(workSessions.updatedAt, staleBefore))
    )).returning({ id: workSessions.id });
    return { ok: true, updated: rows.length };
  }),
  // Pause — records when pause started
  pause: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const [session] = await db.update(workSessions).set({ status: "paused", pausedAt: now, updatedAt: now }).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "active"))).returning();
    return session ?? null;
  }),
  // Resume — adds paused time to total
  resume: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const [current] = await db.select().from(workSessions).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "paused"))).limit(1);
    if (!current) return null;
    const pausedMs = current.pausedAt ? now.getTime() - new Date(current.pausedAt).getTime() : 0;
    const [session] = await db.update(workSessions).set({
      status: "active",
      pausedAt: null,
      totalPausedMs: (current.totalPausedMs ?? 0) + pausedMs,
      updatedAt: now
    }).where(eq(workSessions.id, current.id)).returning();
    return session;
  }),
  // End — finaliza a sessão aberta (e qualquer duplicada legada), somando a pausa em curso
  end: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const open = await db.select().from(workSessions).where(and(
      eq(workSessions.userId, ctx.user.id),
      or2(eq(workSessions.status, "active"), eq(workSessions.status, "paused"))
    )).orderBy(desc(workSessions.startedAt));
    if (open.length === 0) return null;
    let result = null;
    for (const s4 of open) {
      const [ended] = await db.update(workSessions).set({ status: "ended", ...closeSessionValues(s4, now), updatedAt: now }).where(and(eq(workSessions.id, s4.id), or2(eq(workSessions.status, "active"), eq(workSessions.status, "paused")))).returning();
      result ??= ended ?? null;
    }
    return result;
  }),
  // History — last 30 sessions for this user
  history: protectedProcedure.query(async ({ ctx }) => {
    return db.select().from(workSessions).where(eq(workSessions.userId, ctx.user.id)).orderBy(desc(workSessions.startedAt)).limit(30);
  }),
  // Admin: all seller sessions today + recent task activity + last-online history
  allActiveToday: adminProcedure.query(async () => {
    const now = /* @__PURE__ */ new Date();
    const todayStart = spMidnight(now);
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 864e5);
    const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1e3);
    const [allSellers, todaySessions, todayTasks, allRecentSessions, ghostCounts, burstTasks] = await Promise.all([
      db.select().from(sellers).where(eq(sellers.status, "active")),
      // Sessões de hoje (SP), inclusive as já encerradas, mais qualquer sessão ainda
      // aberta (mesmo iniciada antes de 00:00 SP) — pausado também aparece no admin
      db.select().from(workSessions).where(or2(
        gte(workSessions.startedAt, todayStart),
        gte(workSessions.endedAt, todayStart),
        eq(workSessions.status, "active"),
        eq(workSessions.status, "paused")
      )).orderBy(desc(workSessions.startedAt)),
      // Today's edited tasks — include title so we can show what they worked on
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        title: tasks.title,
        lastContactedAt: tasks.lastContactedAt
      }).from(tasks).where(gte(tasks.lastContactedAt, todayStart)).orderBy(desc(tasks.lastContactedAt)),
      // Most recent session per seller in the last 90 days — for "last online" info
      db.select({
        userId: workSessions.userId,
        startedAt: workSessions.startedAt,
        endedAt: workSessions.endedAt,
        status: workSessions.status,
        pausedAt: workSessions.pausedAt,
        totalPausedMs: workSessions.totalPausedMs,
        updatedAt: workSessions.updatedAt,
        dailyGoalHours: workSessions.dailyGoalHours
      }).from(workSessions).where(gte(workSessions.startedAt, new Date(Date.now() - 90 * 864e5))).orderBy(desc(workSessions.startedAt)).limit(200),
      // Ghost count: tasks not contacted in 30+ days (aggregated, no row scan)
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        ghostCount: count()
      }).from(tasks).where(or2(isNull2(tasks.lastContactedAt), lt(tasks.lastContactedAt, thirtyDaysAgo))).groupBy(tasks.userId, tasks.assignedTo),
      // Burst detection: only tasks contacted in last 2 hours (not all tasks)
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        lastContactedAt: tasks.lastContactedAt
      }).from(tasks).where(and(isNotNull(tasks.lastContactedAt), gte(tasks.lastContactedAt, twoHoursAgo)))
    ]);
    return allSellers.map((seller) => {
      const userSessions = todaySessions.filter((s4) => s4.userId === seller.userId);
      const liveSessions = userSessions.filter((s4) => !isForgottenSession(s4, now));
      const forgotten = userSessions.length > liveSessions.length;
      const session = liveSessions.find((s4) => s4.status === "active") ?? liveSessions.find((s4) => s4.status === "paused") ?? null;
      const todayMs = todayWorkedMs(userSessions, now);
      const endedToday = userSessions.filter((s4) => s4.endedAt && new Date(s4.endedAt) >= todayStart);
      const endedTodayAt = endedToday.length > 0 ? new Date(Math.max(...endedToday.map((s4) => new Date(s4.endedAt).getTime()))) : null;
      const mine = todayTasks.filter(
        (t5) => t5.userId === seller.userId || t5.assignedTo === seller.name
      );
      const contactsToday = mine.length;
      const lastActivityDate = mine.length > 0 ? new Date(Math.max(...mine.map((t5) => new Date(t5.lastContactedAt).getTime()))) : null;
      const recentTasks = mine.slice(0, 5).map((t5) => ({
        title: t5.title.split(" - ")[0].slice(0, 60),
        lastContactedAt: t5.lastContactedAt
      }));
      const lastOnlineSession = !session ? allRecentSessions.find((s4) => s4.userId === seller.userId) ?? null : null;
      const lastOnlineAt = lastOnlineSession ? new Date(effectiveEndMs(lastOnlineSession, now)) : null;
      let workedMs = 0;
      let idleSinceMs = 0;
      if (session) {
        workedMs = sessionWorkedMs(session, now);
        if (session.status === "active" && lastActivityDate) {
          idleSinceMs = now.getTime() - lastActivityDate.getTime();
        } else if (session.status === "active" && contactsToday === 0) {
          idleSinceMs = now.getTime() - new Date(session.startedAt).getTime();
        }
      }
      const ghostCount = ghostCounts.filter((g3) => g3.userId === seller.userId || g3.assignedTo === seller.name).reduce((sum, g3) => sum + Number(g3.ghostCount), 0);
      const sellerBurst = burstTasks.filter((t5) => t5.userId === seller.userId || t5.assignedTo === seller.name).filter((t5) => t5.lastContactedAt).sort((a5, b3) => new Date(a5.lastContactedAt).getTime() - new Date(b3.lastContactedAt).getTime());
      let burstMax = 0;
      for (let i4 = 0; i4 < sellerBurst.length; i4++) {
        const base = new Date(sellerBurst[i4].lastContactedAt).getTime();
        const inWin = sellerBurst.filter((t5) => {
          const d3 = new Date(t5.lastContactedAt).getTime() - base;
          return d3 >= 0 && d3 <= 6e5;
        }).length;
        if (inWin > burstMax) burstMax = inWin;
      }
      return {
        sellerId: seller.id,
        name: seller.name,
        email: seller.email,
        session: session ? {
          startedAt: session.startedAt,
          status: session.status,
          pausedAt: session.pausedAt ?? null,
          workedMs
        } : null,
        forgotten,
        todayWorkedMs: todayMs,
        endedTodayAt,
        contactsToday,
        lastActivityDate,
        idleSinceMs,
        recentTasks,
        lastOnlineAt,
        ghostCount,
        burstAlert: burstMax >= 5,
        burstMax
      };
    });
  })
});

