async function waSendRaw(phone, message) {
  const url3 = process.env.WA_SERVER_URL || "https://evolution.salvitarn.com.br";
  const key = process.env.WA_API_KEY;
  if (!key) {
    console.warn("[wa] WA_API_KEY not configured \u2014 skipping");
    return false;
  }
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 9e3);
  try {
    const res = await fetch(`${url3}/send`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "apikey": key },
      body: JSON.stringify({ phone, message }),
      signal: ctrl.signal
    });
    clearTimeout(timer);
    if (!res.ok) {
      console.warn(`[wa] send to ${maskPhone2(phone)} failed: HTTP ${res.status}`);
      return false;
    }
    let body = {};
    try {
      body = await res.json();
    } catch {
    }
    if (body.success === false) {
      console.warn(`[wa] send to ${maskPhone2(phone)} failed: success=false`);
      return false;
    }
    console.log(`[wa] dispatched to ${maskPhone2(phone)}`);
    return true;
  } catch (err) {
    clearTimeout(timer);
    console.warn(`[wa] send to ${maskPhone2(phone)} error: ${err.message}`);
    return false;
  }
}
