// server/lib/radar/abertura.ts
function dataLimiteAbertura(hoje, anos) {
  const d3 = new Date(Date.UTC(hoje.getUTCFullYear() - anos, hoje.getUTCMonth(), hoje.getUTCDate()));
  if (d3.getUTCMonth() !== hoje.getUTCMonth()) d3.setUTCDate(0);
  return d3.toISOString().slice(0, 10);
}

