// server/db/initialAdmin.ts
var REQUIRED_BOOTSTRAP_KEYS = [
  "INITIAL_ADMIN_EMAIL",
  "INITIAL_ADMIN_NAME",
  "INITIAL_ADMIN_PASSWORD"
];
function readInitialAdminConfig(env) {
  const values = Object.fromEntries(
    REQUIRED_BOOTSTRAP_KEYS.map((key) => [key, env[key]?.trim() ?? ""])
  );
  const configured = REQUIRED_BOOTSTRAP_KEYS.filter((key) => values[key].length > 0);
  if (configured.length === 0) return null;
  const missing = REQUIRED_BOOTSTRAP_KEYS.filter((key) => values[key].length === 0);
  if (missing.length > 0) {
    throw new Error(`[bootstrap] configura\xE7\xE3o incompleta; faltam: ${missing.join(", ")}`);
  }
  const email = values.INITIAL_ADMIN_EMAIL.toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error("[bootstrap] INITIAL_ADMIN_EMAIL n\xE3o \xE9 um e-mail v\xE1lido");
  }
  const password = values.INITIAL_ADMIN_PASSWORD;
  if (password.length < 12) {
    throw new Error("[bootstrap] INITIAL_ADMIN_PASSWORD deve ter pelo menos 12 caracteres");
  }
  if (!/[a-z]/.test(password) || !/[A-Z]/.test(password) || !/\d/.test(password) || !/[^A-Za-z0-9]/.test(password)) {
    throw new Error("[bootstrap] INITIAL_ADMIN_PASSWORD deve conter mai\xFAscula, min\xFAscula, n\xFAmero e s\xEDmbolo");
  }
  const normalized = password.toLowerCase().replace(/[^a-z0-9]/g, "");
  const forbidden = ["admin", "password", "senha", "salvita", "atendente"];
  if (forbidden.some((word) => normalized.includes(word))) {
    throw new Error("[bootstrap] INITIAL_ADMIN_PASSWORD cont\xE9m uma palavra previs\xEDvel");
  }
  return {
    email,
    name: values.INITIAL_ADMIN_NAME,
    password
  };
}

// server/db/migrate.ts
var DATABASE_URL = process.env.NEON_DATABASE_URL ?? process.env.DATABASE_URL;
var sql4 = Xs(DATABASE_URL);
async function bootstrapInitialAdminSafe() {
  try {
    await bootstrapInitialAdmin();
  } catch (err) {
    console.error(
      "[bootstrap] administrador inicial N\xC3O criado \u2014",
      err instanceof Error ? err.message : err
    );
  }
}
async function bootstrapInitialAdmin() {
  const config2 = readInitialAdminConfig(process.env);
  if (!config2) return;
  const rows = await sql4`SELECT id FROM users WHERE role = 'admin' LIMIT 1`;
  if (rows.length > 0) return;
  const hash = hashPassword(config2.password);
  const inserted = await sql4`
    INSERT INTO users (name, email, password_hash, role, must_change_password)
    VALUES (${config2.name}, ${config2.email}, ${hash}, 'admin', true)
    ON CONFLICT (email) DO NOTHING
    RETURNING id
  `;
  if (inserted.length === 0) {
    throw new Error(
      `[bootstrap] ${config2.email} j\xE1 existe, mas n\xE3o \xE9 administrador; promova a conta explicitamente antes de iniciar`
    );
  }
  console.log(`[bootstrap] administrador inicial criado para ${config2.email}; troca de senha obrigat\xF3ria`);
}
